const { withAndroidStyles } = require("expo/config-plugins");

/**
 * Disables the OS scrim behind the transparent navigation bar. Edge-to-edge
 * Android otherwise paints a translucent black band over the gesture/3-button
 * area on every screen; the app background is already dark, so the forced
 * contrast only reads as a broken strip. Lives as a config plugin because
 * android/ is gitignored and regenerated by (EAS) prebuild: a direct styles.xml
 * edit never reaches a shipped build.
 */
module.exports = function withAndroidNavBarContrast(config) {
  return withAndroidStyles(config, (c) => {
    const resources = c.modResults.resources;
    resources.$ = resources.$ || {};
    resources.$["xmlns:tools"] = "http://schemas.android.com/tools";
    const appTheme = (resources.style || []).find((s) => s.$.name === "AppTheme");
    if (appTheme) {
      appTheme.item = (appTheme.item || []).filter(
        (i) => i.$.name !== "android:enforceNavigationBarContrast"
      );
      appTheme.item.push({
        $: { name: "android:enforceNavigationBarContrast", "tools:targetApi": "q" },
        _: "false",
      });
    }
    return c;
  });
};
